export function occurrences(hay, needle) {
  let n = 0; let i = -1;
  while ((i = hay.indexOf(needle, i + 1)) !== -1) n++;
  return n;
}

/** Apply the plan. Throws on any entry that matches neither once-BEFORE nor AFTER. */
export function applyPlan(html, plan = PLAN) {
  let out = html;
  const rows = [];
  for (const e of plan) {
    const b = occurrences(out, e.before);
    const a = occurrences(out, e.after);
    // An AFTER may CONTAIN its BEFORE (date-stamp-after-intro inserts after it), so its
    // BEFORE survives the edit; a BEFORE may contain its AFTER (date-stamp-lead deletes
    // from it), so its AFTER pre-exists. Both cases decide on the right count.
    const done = e.after.includes(e.before) ? a >= 1 : b === 0 && a >= 1;
    const prev = (e.previously || []).find((p) => occurrences(out, p) === 1);
    if (done) rows.push({ id: e.id, action: 'already-applied' });
    else if (b === 1) { out = out.replace(e.before, () => e.after); rows.push({ id: e.id, action: 'applied' }); }
    else if (prev) { out = out.replace(prev, () => e.after); rows.push({ id: e.id, action: 'upgraded' }); }
    else throw new Error(`${e.id}: BEFORE found ${b}x, AFTER ${a}x — the live body moved; re-review`);
  }
  return { html: out, rows };
}

const hrefs = (h) => [...h.matchAll(/href="([^"]+)"/g)].map((m) => m[1]);
const visible = (h) => h.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ');

/** Every check the editor's deterministic half makes, plus the claim gate. */
export function verify(before, after) {
  const problems = [];
  const uncited = findUncitedClaims(after);
  if (uncited.length >= UNCITED_THRESHOLD) problems.push(`${uncited.length} uncited claims: ${uncited.map((u) => u.text.slice(0, 70)).join(' | ')}`);
  const stale = findStaleYears(visible(after), new Date().getFullYear());
  if (stale.length) problems.push(`stale years: ${JSON.stringify(stale).slice(0, 200)}`);
  // Fluoride CATEGORY statements ("fluoride toothpaste is proven to ... prevent
  // cavities") are allowed by the 2026-09-13 ruling and stay. What may not exist:
  // the remineralize verb/adjective anywhere, or any claim shape in text WE wrote.
  if (/\bremineraliz(?:e|es|ed|ing)\b/i.test(visible(after))) problems.push('a remineralize verb/adjective remains');
  if (/\bfights? cavit/i.test(visible(after))) problems.push('"fights cavities" remains');
  const claimRes = HEALTH_CLAIM_PATTERNS
    .filter((p) => ['oral-drug-claim', 'therapeutic', 'drug', 'substantiation'].includes(p.category))
    .map((p) => new RegExp(p.pattern.source, 'i'));
  for (const e of PLAN) {
    const t = visible(e.after);
    const hit = claimRes.map((re) => t.match(re)).find(Boolean);
    if (hit) problems.push(`${e.id}: new text carries a claim word "${hit[0]}"`);
  }
  try { assertHtmlComplete({ html: after, stopReason: 'end_turn' }); } catch (e) { problems.push(`html: ${e.message}`); }
  const lost = hrefs(before).filter((h) => !hrefs(after).includes(h) && !h.includes('PMC5024049'));
  if (lost.length) problems.push(`dropped links: ${lost.join(', ')}`);
  return problems;
}

async function main() {
  const apply = process.argv.includes('--apply');
  const { getArticle, updateArticle } = await import('../lib/shopify.js');
  const article = await getArticle(BLOG_ID, ARTICLE_ID);
  if (article.handle !== SLUG) throw new Error(`article ${ARTICLE_ID} is ${article.handle}, expected ${SLUG}`);
  const live = article.body_html || '';
  const { html, rows } = applyPlan(live);
  for (const r of rows) console.log(`  ${r.action.padEnd(16)} ${r.id}`);
  const problems = verify(live, html);
  if (problems.length) {
    console.error('\nABORT, the result fails a check:');
    for (const p of problems) console.error(`  - ${p}`);
    process.exitCode = 1;
    return;
  }
  console.log(`\nChecks pass: uncited claims < ${UNCITED_THRESHOLD}, no stale year, no oral-drug claim, HTML complete, no link dropped.`);
  if (html === live) { console.log('Nothing to change.'); return; }
  if (!apply) { console.log('Dry run, nothing written. Re-run with --apply ON THE SERVER.'); return; }

  const stamp = new Date().toISOString().replace(/[:.]/g, '-');
  const dir = join(ROOT, 'data', 'reports', 'winner-remediation', stamp);
  mkdirSync(dir, { recursive: true });
  writeFileSync(join(dir, 'before.html'), live);
  writeFileSync(join(dir, 'after.html'), html);
  // edit-gate kind: compliance — hand-reviewed claim remediation on a locked winner.
  await updateArticle(BLOG_ID, ARTICLE_ID, { body_html: html });
  // Mirror, so the publisher's next republish carries the fix instead of reverting it.
  const mirror = join(ROOT, 'data', 'posts', SLUG, 'content.html');
  if (existsSync(dirname(mirror))) {
    if (existsSync(mirror)) writeFileSync(join(dir, 'mirror-before.html'), readFileSync(mirror, 'utf8'));
    writeFileSync(mirror, html);
  }
  const check = (await getArticle(BLOG_ID, ARTICLE_ID)).body_html;
  if (check !== html) throw new Error('read-back does not match what was written');
  console.log(`Applied live and to the mirror. Backups: ${dir}`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) main().catch((e) => { console.error(e); process.exit(1); });
